SELECT COUNT(*) FROM (VALUES (1),(2)) c(id)
LEFT JOIN (VALUES (1,50)) p(id,amount) ON p.id=c.id
WHERE p.amount > 0;

SELECT COUNT(*) FROM (
 SELECT seller FROM (VALUES (1,6),(1,5),(2,9),(3,10)) s(seller,amount)
 GROUP BY seller HAVING SUM(amount)>=10
) qualified;

SELECT COUNT(*) FROM (
 SELECT id FROM (VALUES (4),(4)) a(id)
 UNION ALL
 SELECT id FROM (VALUES (4),(9)) b(id)
) events;

SELECT place FROM (
 SELECT score, RANK() OVER (ORDER BY score DESC) AS place
 FROM (VALUES (90),(90),(70)) x(score)
) ranked WHERE score=70;

SELECT val-prev FROM (
 SELECT dev,n,val,LAG(val) OVER(PARTITION BY dev ORDER BY n) AS prev
 FROM (VALUES ('A',1,10),('B',2,50),('A',3,16)) r(dev,n,val)
) samples WHERE dev='A' AND n=3;

SELECT TOP(1) id FROM (VALUES (10,1),(10,2),(10,3),(11,4)) f(tick,id)
WHERE tick>10 OR (tick=10 AND id>2)
ORDER BY tick,id;

WITH lines(total) AS (
 SELECT qty*price FROM (VALUES (2,10),(3,4),(1,25)) d(qty,price)
)
SELECT COUNT(*) FROM lines WHERE total>=20;
